/* MediaPlayer: table-based hierarchical state machine generated by MachinaState (C99). Do not edit by hand. */
#include "MediaPlayer.h"

/* Internal functions */
static size_t RegionOf(Demo_MediaPlayer_State state);
static size_t FirstRegionOf(Demo_MediaPlayer_State state);
static size_t RegionsOf(Demo_MediaPlayer_State state);
static void Trace(Demo_MediaPlayer* m, Demo_MediaPlayer_TraceKind kind, const char* name);
static void Entry_Active(Demo_MediaPlayer* m);
static void Entry_Playing(Demo_MediaPlayer* m);
static void Exit_Active(Demo_MediaPlayer* m);
static void Exit_Playing(Demo_MediaPlayer* m);
static void OnEntry(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void OnExit(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static Demo_MediaPlayer_State Innermost(const Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void ExitState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void EnterState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void EnterRegion(Demo_MediaPlayer* m, size_t region);
static void EnterDefault(Demo_MediaPlayer* m, Demo_MediaPlayer_State state);
static void EnterHistory(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, bool deep);
static void EnterDown(Demo_MediaPlayer* m, Demo_MediaPlayer_State from, Demo_MediaPlayer_State target, bool history);
static void Transition_3(Demo_MediaPlayer* m);
static bool Guard_4(Demo_MediaPlayer* m);
static void Transition_4(Demo_MediaPlayer* m);
static void Transition_7(Demo_MediaPlayer* m);
static bool HandleEvent(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event);
static bool DispatchState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event);
static bool DispatchCore(Demo_MediaPlayer* m, Demo_MediaPlayer_Event event);
static bool Enqueue(Demo_MediaPlayer* m, const Demo_MediaPlayer_QueuedEvent* entry);
static void DrainQueue(Demo_MediaPlayer* m);

static const Demo_MediaPlayer_State kParent[Demo_MediaPlayer_StateCount] = {
    Demo_MediaPlayer_State_None,   /* Stopped */
    Demo_MediaPlayer_State_None,   /* Active */
    Demo_MediaPlayer_State_Active,   /* Playing */
    Demo_MediaPlayer_State_Active,   /* Paused */
    Demo_MediaPlayer_State_None,   /* Ejected */
};
static const unsigned char kRegionOf[Demo_MediaPlayer_StateCount] =   /* region that contains the state */ {
    0,   /* Stopped */
    0,   /* Active */
    1,   /* Playing */
    1,   /* Paused */
    0,   /* Ejected */
};
static const unsigned char kFirstRegion[Demo_MediaPlayer_StateCount] =   /* first own region */ {
    0,   /* Stopped */
    1,   /* Active */
    0,   /* Playing */
    0,   /* Paused */
    0,   /* Ejected */
};
static const unsigned char kRegionsOf[Demo_MediaPlayer_StateCount] =   /* number of own regions */ {
    0,   /* Stopped */
    1,   /* Active */
    0,   /* Playing */
    0,   /* Paused */
    0,   /* Ejected */
};
static const char* const kStateNames[Demo_MediaPlayer_StateCount] = {
    "Stopped",   /* Stopped */
    "Active",   /* Active */
    "Playing",   /* Playing */
    "Paused",   /* Paused */
    "Ejected",   /* Ejected */
};
static const char* const kEventNames[Demo_MediaPlayer_EventCount] = {
    "Play",
    "Pause",
    "Stop",
    "TrackEnd",
    "Eject",
    "Resume",
    "Volume",
};
static const unsigned char kHistoryKind[Demo_MediaPlayer_StateCount] =   /* 0 = none, 1 = shallow, 2 = deep */ {
    0,   /* Stopped */
    1,   /* Active */
    0,   /* Playing */
    0,   /* Paused */
    0,   /* Ejected */
};

static size_t RegionOf(Demo_MediaPlayer_State state) {
    return kRegionOf[state];
}

static size_t FirstRegionOf(Demo_MediaPlayer_State state) {
    return kFirstRegion[state];
}

static size_t RegionsOf(Demo_MediaPlayer_State state) {
    return kRegionsOf[state];
}

Demo_MediaPlayer_State Demo_MediaPlayer_ParentOf(Demo_MediaPlayer_State state) {
    return state == Demo_MediaPlayer_State_None ? Demo_MediaPlayer_State_None : kParent[state];
}

const char* Demo_MediaPlayer_StateName(Demo_MediaPlayer_State state) {
    return state == Demo_MediaPlayer_State_None ? "None" : kStateNames[state];
}

const char* Demo_MediaPlayer_EventName(Demo_MediaPlayer_Event event) {
    return kEventNames[event];
}

static void Trace(Demo_MediaPlayer* m, Demo_MediaPlayer_TraceKind kind, const char* name) {
    if (m->hooks->Trace != NULL) {
        m->hooks->Trace(m->context, kind, name);
    }
}

typedef void (*Handler)(Demo_MediaPlayer* m);

static void Entry_Active(Demo_MediaPlayer* m) {
    m->hooks->powerOnAmp(m->context);
}

static void Entry_Playing(Demo_MediaPlayer* m) {
    m->hooks->startPlayback(m->context);
}

static void Exit_Active(Demo_MediaPlayer* m) {
    m->hooks->powerOffAmp(m->context);
}

static void Exit_Playing(Demo_MediaPlayer* m) {
    m->hooks->stopPlayback(m->context);
}

static const Handler kEntry[Demo_MediaPlayer_StateCount] = {
    NULL,   /* Stopped */
    Entry_Active,   /* Active */
    Entry_Playing,   /* Playing */
    NULL,   /* Paused */
    NULL,   /* Ejected */
};
static const Handler kExit[Demo_MediaPlayer_StateCount] = {
    NULL,   /* Stopped */
    Exit_Active,   /* Active */
    Exit_Playing,   /* Playing */
    NULL,   /* Paused */
    NULL,   /* Ejected */
};
/* owner, initial target, initial action; row r - 1 describes region r */
static const struct { Demo_MediaPlayer_State owner; Demo_MediaPlayer_State initial; Handler action; } kRegions[Demo_MediaPlayer_RegionCount - 1] = {
    { Demo_MediaPlayer_State_Active, Demo_MediaPlayer_State_Playing, NULL },   /* region 1 */
};

static void OnEntry(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    if (kEntry[state] != NULL) {
        kEntry[state](m);
    }
}

static void OnExit(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    if (kExit[state] != NULL) {
        kExit[state](m);
    }
}

static Demo_MediaPlayer_State Innermost(const Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    while (state != Demo_MediaPlayer_State_None && RegionsOf(state) > 0 && m->active[FirstRegionOf(state)] != Demo_MediaPlayer_State_None) {
        state = m->active[FirstRegionOf(state)];
    }
    return state;
}

static void ExitState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    size_t region;
    for (region = FirstRegionOf(state) + RegionsOf(state); region-- > FirstRegionOf(state);) {
        if (m->active[region] != Demo_MediaPlayer_State_None) {
            ExitState(m, m->active[region]);
        }
    }
    Trace(m, Demo_MediaPlayer_Trace_Exit, Demo_MediaPlayer_StateName(state));
    OnExit(m, state);
    m->active[RegionOf(state)] = Demo_MediaPlayer_State_None;
    m->history[RegionOf(state)] = state;
}

static void EnterState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    m->active[RegionOf(state)] = state;
    Trace(m, Demo_MediaPlayer_Trace_Enter, Demo_MediaPlayer_StateName(state));
    OnEntry(m, state);
}

static void EnterRegion(Demo_MediaPlayer* m, size_t region) {
    if (kRegions[region - 1].action != NULL) {
        kRegions[region - 1].action(m);
    }
    EnterDown(m, kRegions[region - 1].owner, kRegions[region - 1].initial, false);
}

static void EnterDefault(Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        EnterRegion(m, region);
    }
}

static void EnterHistory(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, bool deep) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        const Demo_MediaPlayer_State remembered = m->history[region];
        if (remembered == Demo_MediaPlayer_State_None) {
            EnterRegion(m, region);
        } else if (deep) {
            EnterState(m, remembered);
            EnterHistory(m, remembered, true);
        } else {
            EnterDown(m, state, remembered, false);
        }
    }
}

static void EnterDown(Demo_MediaPlayer* m, Demo_MediaPlayer_State from, Demo_MediaPlayer_State target, bool history) {
    Demo_MediaPlayer_State state = target;
    Demo_MediaPlayer_State next = Demo_MediaPlayer_State_None;
    while (Demo_MediaPlayer_ParentOf(state) != from) {
        next = state;
        state = Demo_MediaPlayer_ParentOf(state);
    }
    EnterState(m, state);
    if (next == Demo_MediaPlayer_State_None) {
        if (history) {
            EnterHistory(m, state, kHistoryKind[state] == 2);
            return;
        }
        EnterDefault(m, state);
        return;
    }
    EnterDown(m, state, target, history);
}

typedef bool (*GuardFn)(Demo_MediaPlayer* m);

static void Transition_3(Demo_MediaPlayer* m) {
    m->hooks->resetPosition(m->context);
}

static bool Guard_4(Demo_MediaPlayer* m) {
    return m->hooks->hasNextTrack(m->context);
}

static void Transition_4(Demo_MediaPlayer* m) {
    m->hooks->nextTrack(m->context);
}

static void Transition_7(Demo_MediaPlayer* m) {
    m->hooks->setVolume(m->context, ((const Demo_MediaPlayer_VolumeArgs*)m->args)->level);
}

typedef struct {
    Demo_MediaPlayer_State source;
    Demo_MediaPlayer_Event event;
    GuardFn guard;
    Handler action;
    Demo_MediaPlayer_State target;   /* None for internal transitions */
    Demo_MediaPlayer_State lca;
    bool history;       /* enter target through its history */
    const char* name;
} TransitionRow;

/* source, event, guard, action, target, least common ancestor, history, trace name */
static const TransitionRow kTransitions[9] = {
    { Demo_MediaPlayer_State_Stopped, Demo_MediaPlayer_Event_Play, NULL, NULL, Demo_MediaPlayer_State_Active, Demo_MediaPlayer_State_None, false, "Stopped -> Active" },
    { Demo_MediaPlayer_State_Stopped, Demo_MediaPlayer_Event_Eject, NULL, NULL, Demo_MediaPlayer_State_Ejected, Demo_MediaPlayer_State_None, false, "Stopped -> Ejected" },
    { Demo_MediaPlayer_State_Stopped, Demo_MediaPlayer_Event_Resume, NULL, NULL, Demo_MediaPlayer_State_Active, Demo_MediaPlayer_State_None, true, "Stopped -> Active (history)" },
    { Demo_MediaPlayer_State_Active, Demo_MediaPlayer_Event_Stop, NULL, Transition_3, Demo_MediaPlayer_State_Stopped, Demo_MediaPlayer_State_None, false, "Active -> Stopped" },
    { Demo_MediaPlayer_State_Playing, Demo_MediaPlayer_Event_TrackEnd, Guard_4, Transition_4, Demo_MediaPlayer_State_Playing, Demo_MediaPlayer_State_Active, false, "Playing -> Playing" },
    { Demo_MediaPlayer_State_Playing, Demo_MediaPlayer_Event_Pause, NULL, NULL, Demo_MediaPlayer_State_Paused, Demo_MediaPlayer_State_Active, false, "Playing -> Paused" },
    { Demo_MediaPlayer_State_Playing, Demo_MediaPlayer_Event_TrackEnd, NULL, NULL, Demo_MediaPlayer_State_Stopped, Demo_MediaPlayer_State_None, false, "Playing -> Stopped" },
    { Demo_MediaPlayer_State_Playing, Demo_MediaPlayer_Event_Volume, NULL, Transition_7, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Active, false, "Playing (internal)" },
    { Demo_MediaPlayer_State_Paused, Demo_MediaPlayer_Event_Play, NULL, NULL, Demo_MediaPlayer_State_Playing, Demo_MediaPlayer_State_Active, false, "Paused -> Playing" },
};

static bool TryRow(Demo_MediaPlayer* m, const TransitionRow* row) {
    if (row->guard != NULL && !row->guard(m)) {
        return false;
    }
    Trace(m, Demo_MediaPlayer_Trace_Transition, row->name);
    if (row->target == Demo_MediaPlayer_State_None) {
        if (row->action != NULL) {
            row->action(m);
        }
        return true;
    }
    Demo_MediaPlayer_State root = row->source;
    while (Demo_MediaPlayer_ParentOf(root) != row->lca) {
        root = Demo_MediaPlayer_ParentOf(root);
    }
    ExitState(m, root);
    if (row->action != NULL) {
        row->action(m);
    }
    EnterDown(m, row->lca, row->target, row->history);
    return true;
}

static bool HandleEvent(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event) {
    size_t i;
    for (i = 0; i < 9; ++i) {
        if (kTransitions[i].source == state && kTransitions[i].event == event && TryRow(m, &kTransitions[i])) {
            return true;
        }
    }
    return false;
}

/* Offers the event to every active region below `state` first, then to `state` itself. */
static bool DispatchState(Demo_MediaPlayer* m, Demo_MediaPlayer_State state, Demo_MediaPlayer_Event event) {
    size_t region;
    for (region = FirstRegionOf(state); region < FirstRegionOf(state) + RegionsOf(state); ++region) {
        if (m->active[region] != Demo_MediaPlayer_State_None && DispatchState(m, m->active[region], event)) {
            return true;
        }
    }
    return HandleEvent(m, state, event);
}

static bool DispatchCore(Demo_MediaPlayer* m, Demo_MediaPlayer_Event event) {
    Trace(m, Demo_MediaPlayer_Trace_Event, Demo_MediaPlayer_EventName(event));
    if (m->active[0] != Demo_MediaPlayer_State_None && DispatchState(m, m->active[0], event)) {
        return true;
    }
    Trace(m, Demo_MediaPlayer_Trace_Ignored, Demo_MediaPlayer_EventName(event));
    return false;
}

static bool Enqueue(Demo_MediaPlayer* m, const Demo_MediaPlayer_QueuedEvent* entry) {
    if (m->queueCount == Demo_MediaPlayer_QueueCapacity) {
        return false;
    }
    m->queue[(m->queueHead + m->queueCount) % Demo_MediaPlayer_QueueCapacity] = *entry;
    ++m->queueCount;
    return true;
}

static void DrainQueue(Demo_MediaPlayer* m) {
    while (m->queueCount > 0) {
        const Demo_MediaPlayer_QueuedEvent entry = m->queue[m->queueHead];
        m->queueHead = (m->queueHead + 1) % Demo_MediaPlayer_QueueCapacity;
        --m->queueCount;
        m->args = &entry.args;
        DispatchCore(m, entry.event);
        m->args = NULL;
    }
}

void Demo_MediaPlayer_Init(Demo_MediaPlayer* m, const Demo_MediaPlayer_Hooks* hooks, void* context) {
    size_t i;
    m->hooks   = hooks;
    m->context = context;
    for (i = 0; i < Demo_MediaPlayer_RegionCount; ++i) {
        m->active[i] = Demo_MediaPlayer_State_None;
        m->history[i] = Demo_MediaPlayer_State_None;
    }
    m->queueHead  = 0;
    m->queueCount = 0;
    m->args = NULL;
}

void Demo_MediaPlayer_Start(Demo_MediaPlayer* m) {
    size_t i;
    m->hooks->Lock(m->context);
    for (i = 0; i < Demo_MediaPlayer_RegionCount; ++i) {
        m->active[i] = Demo_MediaPlayer_State_None;
        m->history[i] = Demo_MediaPlayer_State_None;
    }
    m->queueHead  = 0;
    m->queueCount = 0;
    Trace(m, Demo_MediaPlayer_Trace_Start, "MediaPlayer");
    EnterDown(m, Demo_MediaPlayer_State_None, Demo_MediaPlayer_State_Stopped, false);
    DrainQueue(m);
    m->hooks->Unlock(m->context);
}

bool Demo_MediaPlayer_Dispatch(Demo_MediaPlayer* m, Demo_MediaPlayer_Event event) {
    bool handled = false;
    m->hooks->Lock(m->context);
    if (event != Demo_MediaPlayer_Event_Volume) {
        m->args = NULL;
        handled = DispatchCore(m, event);
        m->args = NULL;
        DrainQueue(m);
    }
    m->hooks->Unlock(m->context);
    return handled;
}

bool Demo_MediaPlayer_DispatchVolume(Demo_MediaPlayer* m, int level) {
    bool handled;
    Demo_MediaPlayer_VolumeArgs args;
    args.level = level;
    m->hooks->Lock(m->context);
    m->args = &args;
    handled = DispatchCore(m, Demo_MediaPlayer_Event_Volume);
    m->args = NULL;
    DrainQueue(m);
    m->hooks->Unlock(m->context);
    return handled;
}

bool Demo_MediaPlayer_Post(Demo_MediaPlayer* m, Demo_MediaPlayer_Event event) {
    Demo_MediaPlayer_QueuedEvent entry;
    if (!(event != Demo_MediaPlayer_Event_Volume)) {
        return false;
    }
    entry.event = event;
    return Enqueue(m, &entry);
}

bool Demo_MediaPlayer_PostVolume(Demo_MediaPlayer* m, int level) {
    Demo_MediaPlayer_QueuedEvent entry;
    entry.event = Demo_MediaPlayer_Event_Volume;
    entry.args.Volume.level = level;
    return Enqueue(m, &entry);
}

Demo_MediaPlayer_State Demo_MediaPlayer_Current(const Demo_MediaPlayer* m) {
    Demo_MediaPlayer_State result;
    m->hooks->Lock(m->context);
    result = Innermost(m, m->active[0]);
    m->hooks->Unlock(m->context);
    return result;
}

bool Demo_MediaPlayer_IsIn(const Demo_MediaPlayer* m, Demo_MediaPlayer_State state) {
    bool result;
    m->hooks->Lock(m->context);
    result = state != Demo_MediaPlayer_State_None && m->active[RegionOf(state)] == state;
    m->hooks->Unlock(m->context);
    return result;
}

bool Demo_MediaPlayer_IsFinished(const Demo_MediaPlayer* m) {
    bool result;
    m->hooks->Lock(m->context);
    result = m->active[0] == Demo_MediaPlayer_State_Ejected;
    m->hooks->Unlock(m->context);
    return result;
}

